$('import-json').onclick=()=>$('import-json-file').click();$('import-json-file').onchange=async()=>{const file=$('import-json-file').files[0];if(!file)return;try{if(file.size>60000)throw Error('Choose a tierlist JSON file smaller than 60 KB.');const imported=cleanList(JSON.parse(await file.text()),units);state=imported;recordId=revision=null;selected=null;history.replaceState(null,'',location.pathname);persist();fill();status('Tierlist imported as a new local draft.');document.querySelector('.tierlist-more').open=false}catch(e){status('Could not import: '+e.message)}finally{$('import-json-file').value=''}};
