$('close-share').onclick=()=>$('tierlist-share').close();$('share').onclick=async()=>{$('share-title').value=state.title;$('share-author').value=state.shareAuthor||'';$('share-notes').value=state.notes;$('tierlist-share').showModal();$('share-status').textContent='Preparing image…';try{await drawTierlist($('share-preview'),state,units);$('share-status').textContent='Ready to share.'}catch(e){status(e.message)}};
